"""Snapping span edges to a fixed step for payroll."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span

def check_step(step: int) -> None:
    """A step is whole minutes that divide an hour."""
    if not isinstance(step, int) or step <= 0:
        raise ValueError(f"step must be positive: {step!r}")
    if 60 % step:
        raise ValueError(f"step must divide 60: {step!r}")

def snap(minute: int, step: int) -> int:
    """Nearest multiple of step. Halves round up."""
    return (minute + step // 2) // step * step

def round_span(span: Span, step: int) -> Span:
    """Snap both edges. A collapsed span is an error."""
    check_step(step)
    start = snap(span.start, step)
    return Span(start, snap(span.end, step))

def span_label(span: Span) -> str:
    """Text such as 09:00-17:15 (8h 15m)."""
    hours, extra = divmod(span.minutes, 60)
    return f"{format_span(span)} ({hours}h {extra}m)"

def rounded_labels(
    spans: Iterable[Span], step: int
) -> List[str]:
    """One label per span, after snapping to step."""
    check_step(step)
    snapped = [round_span(span, step) for span in spans]
    return [span_label(span) for span in snapped]

